25	/**
26	 * Shared REST handler base for reindex-management endpoints that all require the same cluster feature gate and capability declaration.
27	 */
28	abstract class AbstractReindexManagementRestHandler extends BaseRestHandler {
29	
30	    private final Predicate<NodeFeature> clusterSupportsFeature;
31	
32	    AbstractReindexManagementRestHandler(final Predicate<NodeFeature> clusterSupportsFeature) {
33	        this.clusterSupportsFeature = Objects.requireNonNull(clusterSupportsFeature);
34	    }
35	
36	    @Override
37	    protected final RestChannelConsumer prepareRequest(final RestRequest request, final NodeClient client) throws IOException {
38	        ensureEndpointSupported();
39	        return innerPrepareRequest(request, client);
40	    }
41	
42	    /**
43	     * Prepares the endpoint-specific request once the cluster-wide compatibility checks have passed.
44	     */
45	    protected abstract RestChannelConsumer innerPrepareRequest(RestRequest request, NodeClient client) throws IOException;
46	
47	    protected final TaskId taskId(final RestRequest request) {
48	        return new TaskId(request.param("task_id"));
49	    }
50	
51	    @Override
52	    public final Set<String> supportedCapabilities() {
53	        return Set.of(CAPABILITY_REINDEX_MANAGEMENT_API);
54	    }
55	
56	    private void ensureEndpointSupported() {
57	        if (clusterSupportsFeature.test(ReindexManagementFeatures.NEW_ENDPOINTS) == false) {
58	            throw new IllegalArgumentException("endpoint not supported on all nodes in the cluster");
59	        }
60	    }
61	}

